"use client";

import React, { useCallback, useState } from "react";
import {
  LayoutDashboard,
  BarChart2,
  FolderKanban,
  Layers,
  Settings,
  CreditCard,
  Users,
  Key,
  LogOut,
  Crown,
  Activity,
  Zap,
  TrendingUp,
  PieChart,
  UserCheck,
  ShieldCheck,
  UserPlus,
  Globe,
  Filter,
  FileText,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { CloseSocket, Drawer, DRAWER_PANEL_CLASS } from "../primitives/Drawer";
import { Nav, NavGroup, NavItem, NavSection } from "../primitives/Nav";

// An app sidebar in the primitives' material: a Drawer on the native <dialog> when it overlays the
// page, or the same raised panel docked inline. Navigation is the Nav primitive, so the current
// page is a raised segment that glides between items and into collapsible sections.

export type SidebarSide = "left" | "right";

export interface SidebarProps {
  /** Controls sidebar visibility */
  isOpen?: boolean;
  /** Callback fired when closing sidebar */
  onClose?: () => void;
  /** Viewport slide placement: "left" or "right" (default: "left") */
  side?: SidebarSide;
  /** Optional custom sidebar body content */
  children?: React.ReactNode;
  /** If true, renders inline inside container instead of fixed screen overlay */
  inline?: boolean;
  /** Custom class names */
  className?: string;
  /** Logo image source URL (default: "/utils/sidebar.png") */
  logoSrc?: string;
}

const WELL = "border border-white/[0.06] bg-[#070707] shadow-[inset_0_1.5px_3px_rgba(0,0,0,0.85),0_1px_0_rgba(255,255,255,0.05)]";

function DefaultNav() {
  const [current, setCurrent] = useState("overview");

  return (
    <Nav aria-label="Main" value={current} onValueChange={setCurrent}>
      <NavGroup label="Workspace">
        <NavSection label="Dashboard" icon={<LayoutDashboard />} defaultOpen>
          <NavItem value="overview" icon={<Activity />}>Overview</NavItem>
          <NavItem value="performance" icon={<TrendingUp />}>Performance</NavItem>
          <NavItem value="traffic" icon={<Zap />} badge="Live">Live traffic</NavItem>
          <NavItem value="summary" icon={<PieChart />}>Executive summary</NavItem>
        </NavSection>
        <NavSection label="Analytics" icon={<BarChart2 />}>
          <NavItem value="demographics" icon={<Globe />}>Audience</NavItem>
          <NavItem value="funnels" icon={<Filter />}>Conversion funnels</NavItem>
          <NavItem value="reports" icon={<FileText />}>Custom reports</NavItem>
        </NavSection>
        <NavItem value="projects" icon={<FolderKanban />}>Projects</NavItem>
        <NavItem value="components" icon={<Layers />} badge="New">Components</NavItem>
      </NavGroup>

      <NavGroup label="Account">
        <NavSection label="Team & access" icon={<Users />}>
          <NavItem value="directory" icon={<UserCheck />}>Members</NavItem>
          <NavItem value="roles" icon={<ShieldCheck />}>Roles</NavItem>
          <NavItem value="invites" icon={<UserPlus />}>Invite links</NavItem>
        </NavSection>
        <NavItem value="api-keys" icon={<Key />}>API keys</NavItem>
        <NavItem value="billing" icon={<CreditCard />}>Billing</NavItem>
        <NavItem value="settings" icon={<Settings />}>Settings</NavItem>
      </NavGroup>
    </Nav>
  );
}

/** A plan card cut into the panel: a tray, an icon socket and a popout tag. No colour. */
function PlanCard() {
  return (
    <div className="rounded-2xl border border-black/50 bg-[#0c0c0d] p-3.5 shadow-[inset_0_2px_6px_rgba(0,0,0,0.7),0_1px_0_rgba(255,255,255,0.05)]">
      <div className="flex items-center gap-2.5">
        <span aria-hidden="true" className={cn("grid size-7 shrink-0 place-items-center rounded-lg text-neutral-300 [&_svg]:size-3.5", WELL)}>
          <Crown />
        </span>
        <span className="min-w-0 flex-1 truncate text-sm font-medium tracking-tight text-neutral-100">Pro plan</span>
        <span className="inline-flex h-5 items-center rounded-md border border-white/40 bg-[linear-gradient(180deg,#f5f5f5_0%,#d9d9d9_100%)] px-1.5 text-[11px] font-medium text-neutral-950 shadow-[inset_0_1px_0_rgba(255,255,255,0.9),inset_0_-1px_0_rgba(0,0,0,0.18),0_1px_2px_rgba(0,0,0,0.6)]">
          Active
        </span>
      </div>
      <p className="mt-2.5 text-[13px] leading-relaxed text-neutral-500">
        Unlimited component exports and API access for your team.
      </p>
    </div>
  );
}

export function Sidebar({
  isOpen: controlledIsOpen,
  onClose: controlledOnClose,
  side = "left",
  children,
  inline = false,
  className,
  logoSrc = "/utils/sidebar.png",
}: SidebarProps) {
  const [uncontrolledIsOpen, setUncontrolledIsOpen] = useState(false);
  const isControlled = controlledIsOpen !== undefined;
  const open = isControlled ? controlledIsOpen : uncontrolledIsOpen;

  const handleClose = useCallback(() => {
    controlledOnClose?.();
    if (!isControlled) setUncontrolledIsOpen(false);
  }, [controlledOnClose, isControlled]);

  const content = (
    <>
      {/* Header: the logo sits in a socket. */}
      <div className="flex shrink-0 items-center gap-3 px-5 pt-5 pb-4">
        <span className={cn("grid size-10 shrink-0 place-items-center overflow-hidden rounded-xl", WELL)}>
          <img src={logoSrc} alt="" className="size-8 object-contain" />
        </span>
        <div className="flex min-w-0 flex-1 flex-col">
          <span className="truncate text-sm font-semibold tracking-[-0.01em] text-neutral-50">AdGrid Studio</span>
          <span className="truncate text-xs text-neutral-500">Pro workspace</span>
        </div>
        {!inline && <CloseSocket onClick={handleClose} />}
      </div>

      {/* Body */}
      <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-3 pb-4 [scrollbar-color:#2a2a2c_transparent] [scrollbar-width:thin]">
        {children ?? (
          <div className="flex flex-col gap-5">
            <DefaultNav />
            <div className="px-0.5">
              <PlanCard />
            </div>
          </div>
        )}
      </div>

      {/* Footer: profile, in the darker tray behind a cut line, like the Dialog footer. */}
      <div className="flex shrink-0 items-center gap-3 border-t border-black/60 bg-black/25 px-4 py-3 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
        <span className={cn("size-9 shrink-0 overflow-hidden rounded-full p-0.5", WELL)}>
          <img src="https://github.com/ajinkya-cell.png" alt="" className="size-full rounded-full object-cover" />
        </span>
        <div className="flex min-w-0 flex-1 flex-col">
          <span className="truncate text-sm font-medium tracking-tight text-neutral-100">Ajinkya</span>
          <span className="truncate text-xs text-neutral-500">ajinkya.org</span>
        </div>
        <button
          type="button"
          onClick={handleClose}
          aria-label="Log out"
          title="Log out"
          className={cn(
            "grid size-8 shrink-0 cursor-pointer place-items-center rounded-lg text-neutral-500 [&_svg]:size-4",
            "transition-colors duration-150 hover:bg-white/[0.04] hover:text-neutral-100",
            "outline-white/40 outline-offset-2 focus-visible:outline focus-visible:outline-1"
          )}
        >
          <LogOut />
        </button>
      </div>
    </>
  );

  if (inline) {
    return (
      <aside aria-label="Sidebar" className={cn(DRAWER_PANEL_CLASS, "mx-auto h-[640px] w-full max-w-[320px]", className)}>
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 z-10 h-[1.5px]"
          style={{
            background:
              "linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.18) 25%, rgba(255,255,255,0.32) 50%, rgba(255,255,255,0.18) 75%, transparent 100%)",
          }}
        />
        {content}
      </aside>
    );
  }

  return (
    <Drawer
      open={open}
      onOpenChange={(next) => {
        if (!next) handleClose();
      }}
      side={side}
      size="sm"
      aria-label="Sidebar"
      className={className}
    >
      {content}
    </Drawer>
  );
}

"use client";

import {
  cloneElement,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  type MouseEvent,
  type ReactElement,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";

// A panel that slides in from the side, on the same native <dialog> as Modal: focus trap, Escape,
// top layer, inert page and focus return come from the browser. It floats 8px off the screen edge
// so the bevel, the prismatic edge and the long drop shadow all read, the same as every other
// raised surface.

const EXIT_MS = 180;
const PRISMATIC =
  "linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.18) 25%, rgba(255,255,255,0.32) 50%, rgba(255,255,255,0.18) 75%, transparent 100%)";

export type DrawerSide = "left" | "right";
export type DrawerSize = "sm" | "md" | "lg";

const WIDTH = { sm: "max-w-[320px]", md: "max-w-[380px]", lg: "max-w-[480px]" };

/** The raised panel material, for showing drawer content inline (e.g. a docked sidebar). */
export const DRAWER_PANEL_CLASS = cn(
  "relative flex flex-col overflow-hidden rounded-3xl text-neutral-100",
  "border border-white/[0.08] border-t-white/[0.16] bg-[linear-gradient(180deg,#1b1b1d_0%,#151516_100%)]",
  "shadow-[inset_0_1.5px_0_0_rgba(255,255,255,0.08),inset_0_-1.5px_0_0_rgba(0,0,0,0.45),0_40px_100px_-20px_rgba(0,0,0,0.9),0_8px_24px_-6px_rgba(0,0,0,0.7)]"
);

/** The round close socket shared with Modal. */
export function CloseSocket({ onClick, className }: { onClick: () => void; className?: string }) {
  return (
    <button
      type="button"
      aria-label="Close"
      onClick={onClick}
      className={cn(
        "grid size-8 shrink-0 cursor-pointer place-items-center rounded-full",
        "border border-white/[0.08] bg-[#0d0d0e] text-neutral-500",
        "shadow-[inset_0_1.5px_3px_rgba(0,0,0,0.8),0_1px_0_rgba(255,255,255,0.06)]",
        "transition-colors duration-150 hover:border-white/[0.14] hover:text-neutral-100",
        "outline-white/40 outline-offset-2 focus-visible:outline focus-visible:outline-1",
        className
      )}
    >
      <svg viewBox="0 0 12 12" width="11" height="11" fill="none" aria-hidden="true">
        <path d="m3 3 6 6M9 3 3 9" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
      </svg>
    </button>
  );
}

const DrawerContext = createContext<{ close: () => void } | null>(null);

/** Closes the surrounding Drawer. Returns a no-op outside one. */
export function useDrawerClose() {
  return useContext(DrawerContext)?.close ?? (() => {});
}

export interface DrawerProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** An element that opens the drawer when clicked. */
  trigger?: ReactElement;
  side?: DrawerSide;
  /** Panel width: 320, 380 or 480px. */
  size?: DrawerSize;
  /** Heading. Without one, the children own the whole panel and `aria-label` names it. */
  title?: ReactNode;
  description?: ReactNode;
  "aria-label"?: string;
  /** Actions in the footer tray. */
  footer?: ReactNode;
  /** Backdrop click and the close socket. Escape always closes. */
  dismissible?: boolean;
  className?: string;
  children?: ReactNode;
}

export function Drawer({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  trigger,
  side = "left",
  size = "md",
  title,
  description,
  "aria-label": ariaLabel,
  footer,
  dismissible = true,
  className,
  children,
}: DrawerProps) {
  const [own, setOwn] = useState(defaultOpen);
  const open = openProp ?? own;
  const setOpen = useCallback(
    (next: boolean) => {
      if (openProp === undefined) setOwn(next);
      onOpenChange?.(next);
    },
    [openProp, onOpenChange]
  );
  const close = useCallback(() => setOpen(false), [setOpen]);

  const ref = useRef<HTMLDialogElement>(null);
  const [state, setState] = useState<"open" | "closed">("closed");
  const pressedBackdrop = useRef(false);
  const closeRef = useRef(close);
  closeRef.current = close;
  const labelId = useId();
  const descId = useId();

  // Same lifecycle as Modal: showModal, then slide in; slide out, then close.
  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open) {
      if (!dialog.open) {
        dialog.showModal();
        dialog.querySelector<HTMLElement>("[data-autofocus]")?.focus();
      }
      const frame = requestAnimationFrame(() => setState("open"));
      return () => cancelAnimationFrame(frame);
    }
    setState("closed");
    if (!dialog.open) return;
    const timer = window.setTimeout(() => dialog.close(), EXIT_MS);
    return () => window.clearTimeout(timer);
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const root = document.documentElement;
    const previous = root.style.overflow;
    root.style.overflow = "hidden";
    return () => {
      root.style.overflow = previous;
    };
  }, [open]);

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    const onCancel = (event: Event) => {
      event.preventDefault();
      closeRef.current();
    };
    const onClose = () => {
      if (open) closeRef.current();
    };
    dialog.addEventListener("cancel", onCancel);
    dialog.addEventListener("close", onClose);
    return () => {
      dialog.removeEventListener("cancel", onCancel);
      dialog.removeEventListener("close", onClose);
    };
  }, [open]);

  const triggerElement = isValidElement<{ onClick?: (event: MouseEvent) => void }>(trigger)
    ? cloneElement(trigger as ReactElement<Record<string, unknown>>, {
        "aria-haspopup": "dialog",
        "aria-expanded": open,
        onClick: (event: MouseEvent) => {
          trigger.props.onClick?.(event);
          if (!event.defaultPrevented) setOpen(true);
        },
      })
    : null;

  const left = side === "left";

  return (
    <>
      {triggerElement}
      <dialog
        ref={ref}
        aria-modal="true"
        aria-labelledby={title ? labelId : undefined}
        aria-describedby={description ? descId : undefined}
        aria-label={title ? undefined : ariaLabel}
        data-state={state}
        data-side={side}
        onPointerDown={(event) => {
          pressedBackdrop.current = event.target === event.currentTarget;
        }}
        onClick={(event) => {
          if (dismissible && pressedBackdrop.current && event.target === event.currentTarget) close();
          pressedBackdrop.current = false;
        }}
        className={cn(
          "group/drawer my-2 h-[calc(100dvh-16px)] max-h-none w-[calc(100vw-16px)] max-w-none overflow-visible border-0 bg-transparent p-0 text-neutral-100 outline-none",
          left ? "mr-auto ml-2" : "mr-2 ml-auto",
          WIDTH[size],
          "backdrop:bg-black/60 backdrop:opacity-0 backdrop:backdrop-blur-[3px]",
          "backdrop:transition-opacity backdrop:duration-[180ms]",
          "data-[state=open]:backdrop:opacity-100 data-[state=open]:backdrop:duration-[260ms]"
        )}
      >
        <DrawerContext.Provider value={{ close }}>
          <div
            className={cn(
              DRAWER_PANEL_CLASS,
              "h-full w-full",
              // Exit (default): quick and accelerating, back past the edge. Entrance: slower and settling.
              left ? "-translate-x-[calc(100%+16px)]" : "translate-x-[calc(100%+16px)]",
              "transition-[translate] duration-[180ms] ease-[cubic-bezier(0.4,0,1,1)]",
              "group-data-[state=open]/drawer:translate-x-0",
              "group-data-[state=open]/drawer:duration-[260ms] group-data-[state=open]/drawer:ease-[cubic-bezier(0.32,0.72,0,1)]",
              // Reduced motion: no slide, just the backdrop fade and an opacity change.
              "motion-reduce:translate-x-0 motion-reduce:opacity-0 motion-reduce:transition-opacity",
              "motion-reduce:group-data-[state=open]/drawer:opacity-100",
              className
            )}
          >
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-0 top-0 z-10 h-[1.5px]"
              style={{ background: PRISMATIC }}
            />

            {(title || description) && (
              <div className="flex shrink-0 items-start justify-between gap-4 px-6 pt-6">
                <div className="flex min-w-0 flex-col gap-1.5">
                  {title && (
                    <h2 id={labelId} className="text-base font-semibold tracking-[-0.02em] text-neutral-50">
                      {title}
                    </h2>
                  )}
                  {description && (
                    <p id={descId} className="text-sm leading-relaxed text-neutral-400">
                      {description}
                    </p>
                  )}
                </div>
                {dismissible && <CloseSocket onClick={close} className="-mt-1 -mr-1" />}
              </div>
            )}

            {title || description ? (
              <div className="min-h-0 flex-1 overflow-y-auto px-6 pt-5 pb-6 text-sm leading-relaxed text-neutral-400">
                {children}
              </div>
            ) : (
              <div className="flex min-h-0 flex-1 flex-col">{children}</div>
            )}

            {footer && (
              <div className="flex shrink-0 flex-wrap items-center justify-end gap-2.5 border-t border-black/60 bg-black/25 px-6 py-4 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
                {footer}
              </div>
            )}
          </div>
        </DrawerContext.Provider>
      </dialog>
    </>
  );
}

"use client";

import {
  createContext,
  forwardRef,
  useContext,
  useId,
  useState,
  type AnchorHTMLAttributes,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
} from "react";
import { LayoutGroup, motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { SEGMENT_CLASS } from "./Tabs";

// Vertical navigation for sidebars and drawers. The current item is the same raised segment as
// Tabs, and it glides between items, including into and out of collapsible sections. Sections
// open on a grid-rows transition, and their children hang off a machined rail.

const SPRING = { type: "spring", stiffness: 500, damping: 32 } as const;

interface NavContextValue {
  value: string;
  select: (value: string) => void;
  reduceMotion: boolean;
}

const NavContext = createContext<NavContextValue | null>(null);
const DepthContext = createContext(0);

function useNav(part: string) {
  const context = useContext(NavContext);
  if (!context) throw new Error(`<${part}> must be used inside <Nav>.`);
  return context;
}

// ─── Nav ────────────────────────────────────────────────────────────────────

export interface NavProps extends Omit<HTMLAttributes<HTMLElement>, "defaultValue" | "onChange"> {
  /** The current item's value. With a router, pass the current path. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export const Nav = forwardRef<HTMLElement, NavProps>(function Nav(
  { value: valueProp, defaultValue = "", onValueChange, className, children, ...rest },
  ref
) {
  const [own, setOwn] = useState(defaultValue);
  const value = valueProp ?? own;
  const reduceMotion = useReducedMotion() ?? false;
  const id = useId();

  const select = (next: string) => {
    if (valueProp === undefined) setOwn(next);
    if (next !== value) onValueChange?.(next);
  };

  return (
    <NavContext.Provider value={{ value, select, reduceMotion }}>
      <nav {...rest} ref={ref} className={cn("flex flex-col gap-5", className)}>
        <LayoutGroup id={id}>{children}</LayoutGroup>
      </nav>
    </NavContext.Provider>
  );
});

// ─── Group ──────────────────────────────────────────────────────────────────

export interface NavGroupProps extends HTMLAttributes<HTMLDivElement> {
  label?: ReactNode;
}

export function NavGroup({ label, className, children, ...rest }: NavGroupProps) {
  const labelId = useId();
  return (
    <div {...rest} role="group" aria-labelledby={label ? labelId : undefined} className={cn("flex flex-col", className)}>
      {label && (
        <div id={labelId} className="px-2.5 pb-1.5 text-xs font-medium text-neutral-500">
          {label}
        </div>
      )}
      <ul className="flex flex-col gap-0.5">{children}</ul>
    </div>
  );
}

// ─── Item ───────────────────────────────────────────────────────────────────

type ItemBase = {
  value: string;
  icon?: ReactNode;
  /** Shown on the right, e.g. a count or "New". */
  badge?: ReactNode;
  disabled?: boolean;
};

export type NavItemProps = ItemBase &
  (
    | ({ href: string } & Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href">)
    | ({ href?: undefined } & Omit<ButtonHTMLAttributes<HTMLButtonElement>, "value">)
  );

const rowClass = (depth: number) =>
  cn(
    "group/nav relative flex w-full cursor-pointer items-center gap-2.5 rounded-lg px-2.5 text-left font-medium tracking-tight select-none",
    "transition-colors duration-150 outline-white/40 -outline-offset-1 focus-visible:outline focus-visible:outline-1",
    depth > 0 ? "h-8 text-[13px]" : "h-9 text-sm"
  );

/** A link (with `href`) or a button. Marks itself `aria-current="page"` when it's the current value. */
export function NavItem(props: NavItemProps) {
  const { value: current, select, reduceMotion } = useNav("NavItem");
  const depth = useContext(DepthContext);
  const { value, icon, badge, disabled, className, children, onClick, ...rest } = props;
  const active = value === current;

  const handleClick = (event: MouseEvent<HTMLAnchorElement & HTMLButtonElement>) => {
    if (disabled) {
      event.preventDefault();
      return;
    }
    (onClick as ((event: MouseEvent) => void) | undefined)?.(event);
    if (!event.defaultPrevented || props.href) select(value);
  };

  const classes = cn(
    rowClass(depth),
    active ? "text-neutral-50" : "text-neutral-400",
    !active && !disabled && "hover:bg-white/[0.03] hover:text-neutral-200",
    disabled && "cursor-not-allowed opacity-40",
    className
  );

  const inner = (
    <>
      {active && (
        <motion.span
          aria-hidden="true"
          layoutId="nav-current"
          transition={reduceMotion ? { duration: 0 } : SPRING}
          className={SEGMENT_CLASS}
        />
      )}
      {icon && (
        <span
          aria-hidden="true"
          className={cn(
            "relative inline-flex shrink-0 transition-colors duration-150 [&_svg]:size-4",
            active ? "text-neutral-100" : "text-neutral-500 group-hover/nav:text-neutral-300"
          )}
        >
          {icon}
        </span>
      )}
      <span className="relative min-w-0 flex-1 truncate">{children}</span>
      {badge != null && (
        <span
          className={cn(
            "relative inline-flex h-5 shrink-0 items-center rounded-md px-1.5 text-[11px] font-medium",
            "border border-white/[0.06] bg-[#070707] text-neutral-400 shadow-[inset_0_1px_2px_rgba(0,0,0,0.8)]"
          )}
        >
          {badge}
        </span>
      )}
    </>
  );

  return (
    <li className="list-none">
      {"href" in props && props.href !== undefined ? (
        <a
          {...(rest as AnchorHTMLAttributes<HTMLAnchorElement>)}
          aria-current={active ? "page" : undefined}
          aria-disabled={disabled || undefined}
          data-state={active ? "active" : "inactive"}
          onClick={handleClick}
          className={classes}
        >
          {inner}
        </a>
      ) : (
        <button
          {...(rest as ButtonHTMLAttributes<HTMLButtonElement>)}
          type="button"
          disabled={disabled}
          aria-current={active ? "page" : undefined}
          data-state={active ? "active" : "inactive"}
          onClick={handleClick}
          className={classes}
        >
          {inner}
        </button>
      )}
    </li>
  );
}

// ─── Section ────────────────────────────────────────────────────────────────

export interface NavSectionProps {
  label: ReactNode;
  icon?: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
  children: ReactNode;
}

/** A collapsible parent. Its items hang off a cut-line rail. */
export function NavSection({
  label,
  icon,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  className,
  children,
}: NavSectionProps) {
  const { reduceMotion } = useNav("NavSection");
  const [own, setOwn] = useState(defaultOpen);
  const open = openProp ?? own;
  const contentId = useId();
  // Clip only while moving, so an open section never cuts off the highlight or focus ring.
  const [settled, setSettled] = useState(open);

  const toggle = () => {
    setSettled(false);
    if (openProp === undefined) setOwn(!open);
    onOpenChange?.(!open);
  };

  return (
    <li className={cn("list-none", className)}>
      <button
        type="button"
        aria-expanded={open}
        aria-controls={contentId}
        data-state={open ? "open" : "closed"}
        onClick={toggle}
        className={cn(rowClass(0), "text-neutral-300 hover:bg-white/[0.03] hover:text-neutral-100")}
      >
        {icon && (
          <span aria-hidden="true" className="inline-flex shrink-0 text-neutral-400 [&_svg]:size-4">
            {icon}
          </span>
        )}
        <span className="min-w-0 flex-1 truncate">{label}</span>
        {/* The chevron sits in a small socket, like the Accordion's. */}
        <span
          aria-hidden="true"
          className={cn(
            "grid size-5 shrink-0 place-items-center rounded-full border border-white/[0.06] bg-[#0d0d0e] text-neutral-500",
            "shadow-[inset_0_1px_2px_rgba(0,0,0,0.8),0_1px_0_rgba(255,255,255,0.05)]"
          )}
        >
          <svg
            viewBox="0 0 12 12"
            width="9"
            height="9"
            fill="none"
            className={cn(
              "transition-transform duration-200 ease-[cubic-bezier(0.32,0.72,0,1)] motion-reduce:transition-none",
              open && "rotate-90"
            )}
          >
            <path d="m4.5 2.5 3.5 3.5-3.5 3.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </span>
      </button>

      <div
        id={contentId}
        // Closed content is out of the tab order and the accessibility tree.
        inert={!open || undefined}
        onTransitionEnd={(event) => {
          if (event.target === event.currentTarget && event.propertyName === "grid-template-rows") setSettled(open);
        }}
        className={cn(
          "grid transition-[grid-template-rows,opacity] duration-[260ms] ease-[cubic-bezier(0.32,0.72,0,1)] motion-reduce:transition-none",
          open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
        )}
      >
        <div className={cn("min-h-0", !(open && (settled || reduceMotion)) && "overflow-hidden")}>
          <DepthContext.Provider value={1}>
            <ul
              className={cn(
                "relative mt-0.5 mb-1 ml-[17px] flex flex-col gap-0.5 pl-2.5",
                // The rail: a dark cut with a faint lit edge beside it.
                "before:absolute before:inset-y-1 before:left-0 before:w-px before:bg-black/70 before:shadow-[1px_0_0_rgba(255,255,255,0.05)]"
              )}
            >
              {children}
            </ul>
          </DepthContext.Provider>
        </div>
      </div>
    </li>
  );
}

"use client";

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useId,
  useState,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { LayoutGroup, motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

// Tabs switch between panels of one view. The list is a well; the active tab is a raised segment
// that slides between tabs (or, for page-level tabs, a prismatic line under the label). Arrow keys
// move focus and select in one step, with a roving tabindex so the list is a single Tab stop.

export type TabsVariant = "segment" | "underline";
export type TabsSize = "sm" | "md" | "lg";

const SPRING = { type: "spring", stiffness: 500, damping: 32 } as const;
const PRISMATIC =
  "linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.18) 25%, rgba(255,255,255,0.32) 50%, rgba(255,255,255,0.18) 75%, transparent 100%)";

// Track heights 32 / 40 / 48; a segment fills the track minus its 4px padding.
const SIZES = {
  sm: { tab: "h-6 px-2.5 text-xs", line: "h-8 px-1 text-xs", gap: "gap-1.5" },
  md: { tab: "h-8 px-3 text-sm", line: "h-10 px-1 text-sm", gap: "gap-2" },
  lg: { tab: "h-10 px-4 text-sm", line: "h-12 px-1 text-[15px]", gap: "gap-2" },
} as const;

/** The raised segment: a small slab lifted out of the well. Shared look with SegmentedControl. */
export const SEGMENT_CLASS = cn(
  "absolute inset-0 rounded-lg border border-white/[0.07] border-t-white/[0.13]",
  "bg-[linear-gradient(180deg,#1f1f21_0%,#18181a_100%)]",
  "shadow-[inset_0_1px_0_rgba(255,255,255,0.06),inset_0_-1px_0_rgba(0,0,0,0.5),0_4px_10px_-4px_rgba(0,0,0,0.8),0_1px_2px_rgba(0,0,0,0.5)]"
);

/** The well the segments sit in. */
export const TRACK_CLASS = cn(
  "rounded-xl border border-white/[0.06] bg-[#070707] p-1",
  "shadow-[inset_0_1.5px_3px_rgba(0,0,0,0.85),0_1px_0_rgba(255,255,255,0.05)]"
);

const safeId = (value: string) => value.replace(/[^\w-]/g, "_");

interface TabsContextValue {
  value: string;
  select: (value: string) => void;
  variant: TabsVariant;
  size: TabsSize;
  baseId: string;
  fullWidth: boolean;
  reduceMotion: boolean;
}

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabs(part: string) {
  const context = useContext(TabsContext);
  if (!context) throw new Error(`<${part}> must be used inside <Tabs>.`);
  return context;
}

// ─── Tabs ───────────────────────────────────────────────────────────────────

export interface TabsProps extends Omit<HTMLAttributes<HTMLDivElement>, "defaultValue" | "onChange"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** "segment" is a raised slab in a well; "underline" is a light line for page-level tabs. */
  variant?: TabsVariant;
  size?: TabsSize;
  /** Tabs share the list's full width equally. */
  fullWidth?: boolean;
}

export const Tabs = forwardRef<HTMLDivElement, TabsProps>(function Tabs(
  {
    value: valueProp,
    defaultValue = "",
    onValueChange,
    variant = "segment",
    size = "md",
    fullWidth = false,
    className,
    children,
    ...rest
  },
  ref
) {
  const [own, setOwn] = useState(defaultValue);
  const value = valueProp ?? own;
  const baseId = useId();
  const reduceMotion = useReducedMotion() ?? false;

  const select = useCallback(
    (next: string) => {
      if (valueProp === undefined) setOwn(next);
      if (next !== value) onValueChange?.(next);
    },
    [valueProp, value, onValueChange]
  );

  return (
    <TabsContext.Provider value={{ value, select, variant, size, baseId, fullWidth, reduceMotion }}>
      <div {...rest} ref={ref} data-variant={variant} className={cn("grid grid-cols-1 gap-4", className)}>
        <LayoutGroup id={baseId}>{children}</LayoutGroup>
      </div>
    </TabsContext.Provider>
  );
});

// ─── List ───────────────────────────────────────────────────────────────────

export type TabsListProps = HTMLAttributes<HTMLDivElement>;

export const TabsList = forwardRef<HTMLDivElement, TabsListProps>(function TabsList(
  { className, onKeyDown, children, ...rest },
  ref
) {
  const { variant, fullWidth, select } = useTabs("TabsList");

  // Automatic activation: moving focus selects. Disabled tabs are skipped.
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    const tabs = Array.from(
      event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]:not([disabled])')
    );
    const current = tabs.indexOf(document.activeElement as HTMLButtonElement);
    if (current === -1) return;
    const target =
      event.key === "ArrowRight" ? tabs[(current + 1) % tabs.length]
      : event.key === "ArrowLeft" ? tabs[(current - 1 + tabs.length) % tabs.length]
      : event.key === "Home" ? tabs[0]
      : event.key === "End" ? tabs[tabs.length - 1]
      : undefined;
    if (!target) return;
    event.preventDefault();
    target.focus();
    select(target.dataset.value!);
  };

  return (
    <div
      {...rest}
      ref={ref}
      role="tablist"
      aria-orientation="horizontal"
      onKeyDown={handleKeyDown}
      className={cn(
        "relative flex items-center",
        fullWidth ? "w-full" : "w-fit max-w-full",
        variant === "segment"
          ? cn(TRACK_CLASS, "gap-0.5 overflow-x-auto [scrollbar-width:none]")
          : // A machined cut line under the row: a dark line with a faint light one beneath it.
            "gap-5 overflow-x-auto border-b border-black/60 shadow-[0_1px_0_rgba(255,255,255,0.05)] [scrollbar-width:none]",
        className
      )}
    >
      {children}
    </div>
  );
});

// ─── Tab ────────────────────────────────────────────────────────────────────

export interface TabProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "value"> {
  value: string;
  /** Shown before the label. */
  icon?: ReactNode;
}

export const Tab = forwardRef<HTMLButtonElement, TabProps>(function Tab(
  { value, icon, disabled, className, children, onClick, ...rest },
  ref
) {
  const { value: selected, select, variant, size, baseId, fullWidth, reduceMotion } = useTabs("Tab");
  const active = value === selected;
  const isSegment = variant === "segment";
  const s = SIZES[size];

  return (
    <button
      {...rest}
      ref={ref}
      type="button"
      role="tab"
      id={`${baseId}-tab-${safeId(value)}`}
      aria-selected={active}
      aria-controls={`${baseId}-panel-${safeId(value)}`}
      tabIndex={active ? 0 : -1}
      disabled={disabled}
      data-value={value}
      data-state={active ? "active" : "inactive"}
      data-disabled={disabled ? "" : undefined}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) select(value);
      }}
      className={cn(
        "relative inline-flex shrink-0 cursor-pointer items-center justify-center font-medium tracking-tight whitespace-nowrap select-none",
        "transition-colors duration-150 [&_svg]:size-4 [&_svg]:shrink-0",
        "outline-white/40 focus-visible:outline focus-visible:outline-1",
        isSegment ? cn(s.tab, "rounded-lg outline-offset-1") : cn(s.line, "rounded-md outline-offset-2"),
        s.gap,
        fullWidth && "flex-1",
        active ? "text-neutral-100" : "text-neutral-500 hover:text-neutral-400",
        "disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:text-neutral-500",
        className
      )}
    >
      {active &&
        (isSegment ? (
          <motion.span
            aria-hidden="true"
            layoutId="tabs-indicator"
            transition={reduceMotion ? { duration: 0 } : SPRING}
            className={SEGMENT_CLASS}
          />
        ) : (
          <motion.span
            aria-hidden="true"
            layoutId="tabs-indicator"
            transition={reduceMotion ? { duration: 0 } : SPRING}
            className="absolute inset-x-0 bottom-0 h-[1.5px]"
            style={{ background: PRISMATIC }}
          />
        ))}
      {icon && <span className="relative inline-flex">{icon}</span>}
      <span className="relative">{children}</span>
    </button>
  );
});

// ─── Panel ──────────────────────────────────────────────────────────────────

export interface TabsPanelProps extends HTMLAttributes<HTMLDivElement> {
  value: string;
}

/**
 * Every panel sits in the same grid cell, so the area is always as tall as the tallest panel and
 * switching never moves the tabs or what's below. Inactive panels are hidden (no focus, not read
 * out); the active one settles in with a short fade.
 */
export const TabsPanel = forwardRef<HTMLDivElement, TabsPanelProps>(function TabsPanel(
  { value, className, children, ...rest },
  ref
) {
  const { value: selected, baseId, reduceMotion } = useTabs("TabsPanel");
  const active = value === selected;

  return (
    <motion.div
      {...(rest as Record<string, unknown>)}
      ref={ref}
      role="tabpanel"
      id={`${baseId}-panel-${safeId(value)}`}
      aria-labelledby={`${baseId}-tab-${safeId(value)}`}
      tabIndex={active ? 0 : -1}
      data-state={active ? "active" : "inactive"}
      initial={false}
      animate={active ? { opacity: 1, y: 0 } : { opacity: 0, y: reduceMotion ? 0 : 4 }}
      transition={active && !reduceMotion ? { duration: 0.2, ease: [0.32, 0.72, 0, 1] } : { duration: 0 }}
      className={cn(
        "col-start-1 row-start-2 rounded-xl outline-white/40 outline-offset-2 focus-visible:outline focus-visible:outline-1",
        !active && "pointer-events-none invisible",
        className
      )}
    >
      {children}
    </motion.div>
  );
});

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
